Aprender Espanhol Online: Professores Nativos e Bilíngues Curso de Espanhol Online com Professores Nativos e Bilíngues 2 - Aprender Espanhol Online: Professores Nativos e Bilíngues || html {
scroll-behavior: smooth;
scroll-padding-top: 110px;
}
/* BARRA FIXA */
.topbar {
position: fixed;
top: 0;
left: 0;
width: 100%;
min-height: 82px;
z-index: 9999;
display: flex;
justify-content: space-between;
align-items: center;
gap: 20px;
padding: 8px 28px;
background: #087BB2;
box-shadow: 0 3px 12px rgba(0,0,0,.15);
box-sizing: border-box;
font-family: inherit;
}
/* LOGOMARCA */
.topbar-logo {
display: flex;
align-items: center;
flex-shrink: 0;
line-height: 0;
}
.topbar-logo img {
display: block;
width: 175px;
max-width: 100%;
height: 64px;
object-fit: contain;
}
/* MENU DESKTOP */
.topbar-menu {
display: flex;
align-items: center;
justify-content: flex-end;
gap: 18px;
}
/* LINKS BRANCOS */
.topbar-menu > a.link-menu,
.topbar-menu > a.link-menu:link,
.topbar-menu > a.link-menu:visited,
.topbar-menu > a.link-menu:hover,
.topbar-menu > a.link-menu:focus,
.topbar-menu > a.link-menu:active {
color: #ffffff !important;
font-size: 14px;
font-weight: 500;
white-space: nowrap;
text-decoration: none !important;
transition: .2s ease;
}
.topbar-menu > a.link-menu:hover {
opacity: .82;
}
/* BOTÃO ACESSAR */
.entrar-container {
position: relative;
flex-shrink: 0;
}
.btn-entrar {
background: #25D366;
color: #ffffff;
padding: 9px 20px;
border-radius: 9px;
font-size: 14px;
font-weight: 600;
border: none;
cursor: pointer;
white-space: nowrap;
transition: .25s ease;
animation: pulseButton 6s infinite;
}
.btn-entrar:hover {
background: #1ebe5d;
color: #ffffff;
transform: translateY(-2px);
}
/* SUBMENU */
.submenu-entrar {
display: none;
position: absolute;
top: calc(100% + 12px);
right: 0;
min-width: 215px;
background: #ffffff;
border-radius: 10px;
box-shadow: 0 8px 25px rgba(0,0,0,.18);
padding: 8px;
z-index: 10000;
}
.submenu-entrar a {
display: block;
padding: 12px 14px;
color: #333333 !important;
font-size: 14px;
font-weight: 500;
border-radius: 7px;
white-space: nowrap;
text-decoration: none !important;
transition: .2s ease;
}
.submenu-entrar a:hover {
background: #f0f8fc;
color: #087BB2 !important;
}
/* ABRIR SUBMENU */
.entrar-container.aberto .submenu-entrar {
display: block;
}
/* BOTÃO HAMBURGUER - OCULTO NO DESKTOP */
.menu-toggle {
display: none;
width: 42px;
height: 42px;
padding: 9px;
border: 1px solid rgba(255,255,255,.35);
border-radius: 8px;
background: transparent;
cursor: pointer;
align-items: center;
justify-content: center;
flex-direction: column;
gap: 5px;
flex-shrink: 0;
}
.menu-toggle span {
display: block;
width: 21px;
height: 2px;
border-radius: 3px;
background: #ffffff;
transition: transform .3s ease, opacity .2s ease;
}
/* ANIMAÇÃO DO HAMBURGUER */
.menu-toggle.ativo span:nth-child(1) {
transform: translateY(7px) rotate(45deg);
}
.menu-toggle.ativo span:nth-child(2) {
opacity: 0;
}
.menu-toggle.ativo span:nth-child(3) {
transform: translateY(-7px) rotate(-45deg);
}
/* PULSAÇÃO SUAVE */
@keyframes pulseButton {
0% {
transform: scale(1);
box-shadow: 0 0 0 0 rgba(37,211,102,0);
}
2% {
transform: scale(1.018);
box-shadow: 0 0 10px rgba(37,211,102,.18);
}
4% {
transform: scale(1);
box-shadow: 0 0 0 0 rgba(37,211,102,0);
}
100% {
transform: scale(1);
box-shadow: 0 0 0 0 rgba(37,211,102,0);
}
}
/* COMPENSA A ALTURA DA BARRA */
body {
padding-top: 95px !important;
}
/* TABLET */
@media (max-width: 1024px) and (min-width: 769px) {
.topbar {
gap: 12px;
padding: 8px 16px;
}
.topbar-menu {
gap: 12px;
}
.topbar-logo img {
width: 145px;
height: 58px;
}
.topbar-menu > a.link-menu {
font-size: 13px;
}
.btn-entrar {
padding: 8px 14px;
font-size: 13px;
}
}
/* =========================
MOBILE - MENU HAMBURGUER
========================= */
@media (max-width: 768px) {
/* BARRA SUPERIOR */
.topbar {
min-height: 68px;
height: 68px;
padding: 7px 16px;
justify-content: space-between;
align-items: center;
gap: 10px;
}
/* LOGO À ESQUERDA */
.topbar-logo {
width: auto;
justify-content: flex-start;
}
.topbar-logo img {
width: 145px;
height: 52px;
}
/* HAMBURGUER À DIREITA */
.menu-toggle {
display: flex;
}
/* PAINEL DO MENU */
.topbar-menu {
position: absolute;
top: 100%;
left: 0;
width: 100%;
display: flex;
flex-direction: column;
align-items: stretch;
justify-content: flex-start;
gap: 0;
padding: 0 20px;
background: #087BB2;
box-sizing: border-box;
max-height: 0;
overflow: hidden;
opacity: 0;
visibility: hidden;
pointer-events: none;
box-shadow: 0 8px 15px rgba(0,0,0,.12);
transition:
max-height .4s ease,
opacity .3s ease,
padding .3s ease,
visibility .3s ease;
}
/* MENU ABERTO */
.topbar-menu.menu-aberto {
max-height: 80vh;
overflow-y: auto;
opacity: 1;
visibility: visible;
pointer-events: auto;
padding: 12px 20px 20px;
}
/* LINKS MOBILE */
.topbar-menu > a.link-menu,
.topbar-menu > a.link-menu:link,
.topbar-menu > a.link-menu:visited,
.topbar-menu > a.link-menu:hover,
.topbar-menu > a.link-menu:focus,
.topbar-menu > a.link-menu:active

Aprender Espanhol Online: Professores Nativos e Bilíngues Conheça a Nossa História || (function(w,d,u){
